import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int h = sc.nextInt();
        int n = sc.nextInt();
        int z = 2;
        int z1 = 1;
        int p = 0;
        int r = 0;
        int h2 = 0;
        int h3 = (int) Math.pow(2, h);
        while (p < h) {
            if (n <= h2 + h3 / z && r == 0) {
                z1 += 1;
                z *= 2;
                r = 1;
            } else if (n > h2 + h3 / z && r == 0) {
                h2 += h3 / z;
                z1 += (int) Math.pow(2, h - p);
                z *= 2;
                r = 0;
            } else if (n <= h2 + h3 / z && r == 1) {
                z1 += (int) Math.pow(2, h - p);
                z *= 2;
                r = 1;
            } else if (n > h2 + h3 / z && r == 1) {
                h2 += h3 / z;
                z1 += 1;
                z *= 2;
                r = 0;
            }
            p++;
        }
        System.out.println(z1 - 1);
    }
}
